/// <summary>
/// This is a contract class
/// CB355_DutyRollMonthly
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(METDutyRollMonthlyUIBuilder))
]
class METDutyRollMonthlyContract extends METSysOperationTaskDataContract
{
    private List    itemList = new List(Types::String);
    private List    siteList = new List(Types::String);
    private boolean adHoc;
    private boolean runForExcise;
    private boolean immediateChange;
    private guid    topPickingProcessId;

}

Method.Source:
/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}

    /// <summary>
    /// Provides thread count parameter
    /// </summary>
    /// <param name = "_threadCount">Number of sub tasks spawned from main tasks</param>
    /// <returns>The thread count</returns>
    [DataMember, SysOperationControlVisibilityAttribute(false)]
    public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
    {
        threadCount = _threadCount;

        return threadCount;
    }

    /// <summary>
    /// Validates data contract.
    /// </summary>
    /// <returns>True, if validated; otherwise, false.</returns>
    public boolean validate()
    {
        boolean ret = true;

        if (threadCount <= 0)
        {
            ret = checkFailed("@MET:DutyRollMonthlyValidationThreadCountWarning");
        }

        return ret;
    }

/// <summary>
/// Item query
